// Package otelsemconv pins the OTel semantic-conventions version this
// processor targets and exports the gen_ai.* attribute keys it emits, along
// with the type each key is defined to carry.
//
// Types come from types_<version>_gen.go, generated by Weaver from a pinned
// release of open-telemetry/semantic-conventions.
//
// Bumping versions: run `make generate-semconv-types SEMCONV_TAG=vX.Y.Z`, add
// the new map to typesByTarget below, update the conventions import path and
// defaultTarget to match, and bump version references in public docs.
//
// Adding a new attribute: one line, string(conventions.GenAIFooBarKey). Its
// type is already in the generated map, and Coerce enforces it at write time.
package otelsemconv // import "github.com/open-telemetry/opentelemetry-collector-contrib/processor/genainormalizerprocessor/internal/otelsemconv"

import (
	"go.opentelemetry.io/otel/attribute"
	conventions "go.opentelemetry.io/otel/semconv/v1.40.0"
)

// SchemaURL is the OTel semconv schema URL for the targeted version.
const SchemaURL = conventions.SchemaURL

// defaultTarget names the semconv release whose types this processor enforces.
// It must agree with the conventions import above and with SchemaURL;
// TestDefaultTargetMatchesSchemaURL checks all three.
//
// SchemaURL and the operation-name enum values below come from that single
// import, so selecting a different table here without also moving the import
// would stamp spans with the wrong schema URL.
const defaultTarget = "v1.40.0"

// typesByTarget indexes the generated tables by semconv release. Weaver runs
// once per release, so this index is hand-written.
//
// More than one entry is expected eventually. gen_ai.* was deprecated out of
// semantic-conventions at v1.42.0 and moved to semantic-conventions-genai,
// which has no releases, so the release this component targets and the semconv
// version the repository mandates will not stay the same.
//
//nolint:gochecknoglobals // index over generated lookup tables
var typesByTarget = map[string]map[string]kind{
	"v1.40.0": typesV1_40_0,
}

// targetTypes maps every gen_ai.* key the targeted release defines to the type
// it carries. Keys absent from the map are passed through unchecked.
//
//nolint:gochecknoglobals // generated lookup table selected by defaultTarget
var targetTypes = typesByTarget[defaultTarget]

// enumValue extracts the string value from a semconv enum KeyValue (e.g.
// conventions.GenAIOperationNameChat). The semconv library exposes these as
// pre-built attribute.KeyValue with a String value, so we unwrap once at
// init rather than at every call site.
func enumValue(kv attribute.KeyValue) string {
	return kv.Value.AsString()
}

// GenAI attribute keys, grouped by subnamespace. Adding a new attribute is one
// line: string(conventions.GenAIFooBarKey).
const (
	// gen_ai.agent.*
	GenAIAgentName = string(conventions.GenAIAgentNameKey)

	// gen_ai.conversation.*
	GenAIConversationID = string(conventions.GenAIConversationIDKey)

	// gen_ai.input.*
	GenAIInputMessages = string(conventions.GenAIInputMessagesKey)

	// gen_ai.operation.*
	GenAIOperationName = string(conventions.GenAIOperationNameKey)

	// gen_ai.output.*
	GenAIOutputMessages = string(conventions.GenAIOutputMessagesKey)

	// gen_ai.provider.*
	GenAIProviderName = string(conventions.GenAIProviderNameKey)

	// gen_ai.request.*
	GenAIRequestFrequencyPenalty = string(conventions.GenAIRequestFrequencyPenaltyKey)
	GenAIRequestMaxTokens        = string(conventions.GenAIRequestMaxTokensKey)
	GenAIRequestModel            = string(conventions.GenAIRequestModelKey)
	GenAIRequestPresencePenalty  = string(conventions.GenAIRequestPresencePenaltyKey)
	GenAIRequestStopSequences    = string(conventions.GenAIRequestStopSequencesKey)
	GenAIRequestTemperature      = string(conventions.GenAIRequestTemperatureKey)
	GenAIRequestTopK             = string(conventions.GenAIRequestTopKKey)
	GenAIRequestTopP             = string(conventions.GenAIRequestTopPKey)

	// gen_ai.response.*
	GenAIResponseFinishReasons = string(conventions.GenAIResponseFinishReasonsKey)
	GenAIResponseModel         = string(conventions.GenAIResponseModelKey)

	// gen_ai.tool.*
	GenAIToolCallArguments = string(conventions.GenAIToolCallArgumentsKey)
	GenAIToolCallID        = string(conventions.GenAIToolCallIDKey)
	GenAIToolDefinitions   = string(conventions.GenAIToolDefinitionsKey)
	GenAIToolDescription   = string(conventions.GenAIToolDescriptionKey)
	GenAIToolName          = string(conventions.GenAIToolNameKey)

	// gen_ai.usage.*
	GenAIUsageInputTokens  = string(conventions.GenAIUsageInputTokensKey)
	GenAIUsageOutputTokens = string(conventions.GenAIUsageOutputTokensKey)
)

// gen_ai.operation.name enum values, sourced from the semconv library.
// Source-side normalizers (openinference, openllmetry) fold their own
// span-kind/operation-type enums onto these.
//
//nolint:gochecknoglobals // canonical enum value registry
var (
	GenAIOperationNameChat           = enumValue(conventions.GenAIOperationNameChat)
	GenAIOperationNameEmbeddings     = enumValue(conventions.GenAIOperationNameEmbeddings)
	GenAIOperationNameExecuteTool    = enumValue(conventions.GenAIOperationNameExecuteTool)
	GenAIOperationNameInvokeAgent    = enumValue(conventions.GenAIOperationNameInvokeAgent)
	GenAIOperationNameRetrieval      = enumValue(conventions.GenAIOperationNameRetrieval)
	GenAIOperationNameTextCompletion = enumValue(conventions.GenAIOperationNameTextCompletion)

	// GenAIOperationNameInvokeWorkflow is not part of the standard enum. It
	// is emitted by openllmetry's traceloop.span.kind=workflow path; we keep
	// it as a centralized constant so callers don't need to hard-code the
	// raw string.
	GenAIOperationNameInvokeWorkflow = "invoke_workflow"
)
